// Regenerate the Go port of every assertion in the pinned latex.test.ts:
// node test/parity/testdata/latex-upstream-cases.mjs | gofmt > internal/latex/upstream_test.go
// node test/parity/testdata/latex-upstream-cases.mjs --corpus > internal/latex/testdata/upstream-corpus.txt
// Expected values come from the upstream tests, never from Pig. The generator also checks them against the installed pinned Pi renderer.
import assert from "node:assert/strict";
import { readFileSync, realpathSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";
import { runInNewContext } from "node:vm";
import { pathToFileURL } from "node:url";
import { dirname, resolve } from "node:path";
import ts from "../../../extensions/sdk-ts/node_modules/typescript/lib/typescript.js";

const pkg = realpathSync("extensions/sdk-ts/node_modules/@earendil-works/pi-coding-agent/package.json");
const { renderLatex } = await import(pathToFileURL(resolve(dirname(pkg), "node_modules/@earendil-works/pi-tui/dist/latex.js")).href);
assert.equal(JSON.parse(readFileSync(pkg, "utf8")).version, "1.0.0");
const path = ".upstream/current/packages/tui/test/latex.test.ts";
const source = readFileSync(path, "utf8");
const ast = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true);
const rowLines = new Map();
function walk(node) {
 if (ts.isCallExpression(node) && node.expression.getText(ast) === "defineCases") {
  for (const row of node.arguments[0].elements) {
   const [input] = runInNewContext(row.getText(ast));
   const lines = rowLines.get(input) ?? [];
   lines.push(ast.getLineAndCharacterOfPosition(row.getStart(ast)).line + 1);
   rowLines.set(input, lines);
  }
 }
 ts.forEachChild(node, walk);
}
walk(ast);
let code = stripTypeScriptTypes(source);
code = code.replace(/^import .*;$/gm, "");
const groups = [];
const cases = [];
let current;
let pending;
runInNewContext(code, {
 describe(name, fn) { groups.push(name); fn(); groups.pop(); },
 it(name, fn) {
  const stack = new Error().stack;
  const line = Number(stack.match(/latex\.test\.ts:(\d+):/)[1]);
  current = { name: [...groups, name].join("/"), line, assertions: [] };
  cases.push(current);
  fn();
 },
 renderLatex(input, options) {
  pending = { input, display: options?.display ?? false };
  return renderLatex(input, options);
 },
 assert: { strictEqual(actual, expected) {
  assert.equal(actual, expected);
  const line = current.line === 9 ? rowLines.get(pending.input).shift() : current.line;
  current.assertions.push({ ...pending, expected, line });
 } },
}, { filename: "latex.test.ts" });
const q = JSON.stringify;
if (process.argv.includes("--corpus")) {
 for (const c of cases) for (const a of c.assertions) console.log(q(a.input));
 process.exit(0);
}
console.log('// Code generated by test/parity/testdata/latex-upstream-cases.mjs; DO NOT EDIT.\npackage latex\n\nimport "testing"\n\nfunc TestUpstreamRenderLatex(t *testing.T) {');
for (const c of cases) {
 console.log(` // ${path}:${c.assertions[0].line}\n t.Run(${q(c.name)}, func(t *testing.T) {`);
 for (const a of c.assertions) {
  console.log(`  if got, ok := RenderLatex(${q(a.input)}, RenderLatexOptions{Display: ${a.display}}); ok != ${a.expected !== undefined} || got != ${q(a.expected ?? "")} { t.Errorf("RenderLatex(%q) = (%q, %v), want (%q, %v)", ${q(a.input)}, got, ok, ${q(a.expected ?? "")}, ${a.expected !== undefined}) }`);
 }
 console.log(" })");
}
console.log("}");
console.error(`${cases.length} cases, ${cases.reduce((n, c) => n + c.assertions.length, 0)} assertions verified against Pi 1.0.0`);
